public class SignatureHandlerHandleTests {

    /** 签名列表文件在包内的绝对路径 */
    private static final String SIG_LOC_ABS = "/Doc_0/Signs/Signatures.xml";

    /** 签名目录（Signs）在包内的相对路径 */
    private static final String SIGNS_DIR = "Doc_0/Signs";

    private Path workDir;

    @BeforeEach
    void setUp() throws IOException {
        workDir = Files.createTempDirectory("sig-handler-test-");
    }

    @AfterEach
    void tearDown() throws IOException {
        if (workDir != null && Files.exists(workDir)) {
            try (Stream<Path> walk = Files.walk(workDir)) {
                walk.sorted(Comparator.reverseOrder()).forEach(p -> {
                    try {
                        Files.deleteIfExists(p);
                    } catch (IOException ignored) {
                        // 清理失败不影响测试结果
                    }
                });
            }
        }
    }

    // ------------------------------------------------------------------
    // 正常场景
