    @Test
    @DisplayName("包含多个签名：删除 Sign_N 目录、Signatures.xml 以及 OFD.xml 中的 Signatures 引用")
    void handleRemovesSignatureDirsAndSignaturesEntry() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeSignatures(
                "  <Signature ID=\"s001\" Type=\"Seal\" BaseLoc=\"Sign_0/Signature.xml\"/>",
                "  <Signature ID=\"s002\" Type=\"Sign\" BaseLoc=\"Sign_1/Signature.xml\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");
        writeFile(SIGNS_DIR + "/Sign_0/Seal.esl", "seal");
        writeFile(SIGNS_DIR + "/Sign_1/Signature.xml", "<Signature/>");

        runHandler();

        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "签名描述目录 Sign_0 应被递归删除");
        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR + "/Sign_1")),
                "签名描述目录 Sign_1 应被递归删除");
        assertFalse(Files.exists(workDir.resolve("Doc_0/Signs/Signatures.xml")),
                "签名列表文件 Signatures.xml 应被删除");
        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR)),
                "签名目录 Signs 变空后应被删除");

        String ofdXml = readOfdXml();
        assertFalse(ofdXml.contains("<Signatures>"), "OFD.xml 中不应再包含 Signatures 引用");
        assertTrue(ofdXml.contains("Doc_0/Document.xml"), "DocRoot 引用应保留");
        assertTrue(Files.exists(workDir.resolve("Doc_0/Document.xml")), "文档内容文件应保留");

        // 使用新的读取器验证 OFD.xml 依然合法且不再引用签名列表
        try (OFDReader fresh = new OFDReader(workDir.toAbsolutePath().toString(), false)) {
            assertNull(fresh.getDefaultDocSignaturesPath(),
                    "更新后的 OFD.xml 不应再给出签名列表路径");
        }
    }

    @Test
    @DisplayName("Signs 目录中还有其它文件时保留该目录")
    void handleKeepsSignsDirWhenNotEmpty() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeSignatures("  <Signature ID=\"s001\" BaseLoc=\"Sign_0/Signature.xml\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");
        writeFile(SIGNS_DIR + "/keep.txt", "keep me");

        runHandler();

        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "签名描述目录 Sign_0 应被删除");
        assertFalse(Files.exists(workDir.resolve("Doc_0/Signs/Signatures.xml")),
                "签名列表文件 Signatures.xml 应被删除");
        assertTrue(Files.isDirectory(workDir.resolve(SIGNS_DIR)),
                "Signs 目录非空，应被保留");
        assertEquals("keep me", readFile(SIGNS_DIR + "/keep.txt"),
                "Signs 目录中的其它文件不应被删除");
    }

    @Test
    @DisplayName("签名列表路径使用不带前导斜杠的相对路径时同样可以定位并删除签名目录")
    void handleSupportsRelativeSignaturesLocation() throws IOException {
        writeOfdXml("<Signatures>Signs/Signatures.xml</Signatures>");
        writeDocumentXml();
        writeFile("Signs/Signatures.xml",
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                        + "<Signatures><Signature ID=\"s001\" BaseLoc=\"Sign_0/Signature.xml\"/></Signatures>");
        writeFile("Signs/Sign_0/Signature.xml", "<Signature/>");

        runHandler();

        assertFalse(Files.exists(workDir.resolve("Signs/Sign_0")),
                "相对路径定位到的 Sign_0 目录应被删除");
        assertFalse(Files.exists(workDir.resolve("Signs/Signatures.xml")),
                "相对于工作目录根解析的 Signatures.xml 应被删除");
        assertFalse(Files.exists(workDir.resolve("Signs")),
                "空的 Signs 目录应被删除");
        assertFalse(readOfdXml().contains("<Signatures>"),
                "OFD.xml 中不应再包含 Signatures 引用");
    }

    @Test
    @DisplayName("一个 DocBody 未给出签名列表路径时不做任何处理")
    void handleDoesNothingWhenSignaturesLocationMissing() throws IOException {
        writeOfdXml("");
        writeDocumentXml();
        writeSignatures("  <Signature ID=\"s001\" BaseLoc=\"Sign_0/Signature.xml\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");

        runHandler();

        assertTrue(Files.exists(workDir.resolve("Doc_0/Signs/Signatures.xml")),
                "没有签名引用时 Signatures.xml 不应被删除");
        assertTrue(Files.isDirectory(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "没有签名引用时 Sign_N 目录不应被删除");
        assertTrue(readOfdXml().contains("Doc_0/Document.xml"), "OFD.xml 应保持原样");
    }

    @Test
    @DisplayName("DocBody 引用了签名列表但文件不存在时提前返回且不修改 OFD.xml")
    void handleDoesNothingWhenSignaturesFileMissing() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");

        runHandler();

        assertTrue(Files.isDirectory(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "无法读取签名列表时不应删除 Sign_N 目录");
        assertTrue(readOfdXml().contains("<Signatures>" + SIG_LOC_ABS + "</Signatures>"),
                "无法读取签名列表时 OFD.xml 应保持不变");
    }

    @Test
    @DisplayName("签名列表为空时提前返回，不删除签名列表文件")
    void handleDoesNothingWhenSignatureListEmpty() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeFile(SIGNS_DIR + "/Signatures.xml",
                "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<Signatures/>");

        runHandler();

        assertTrue(Files.exists(workDir.resolve("Doc_0/Signs/Signatures.xml")),
                "签名列表为空时不应删除 Signatures.xml");
        assertTrue(readOfdXml().contains("<Signatures>"), "OFD.xml 应保持不变");
    }

    // ------------------------------------------------------------------
    // BaseLoc 的边界处理
    // ------------------------------------------------------------------

    @Test
    @DisplayName("BaseLoc 为多级路径时仅删除其最顶层的目录")
    void handleDeletesOnlyTopLevelDirOfNestedBaseLoc() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeSignatures("  <Signature ID=\"s001\" BaseLoc=\"Sign_0/sub/Signature.xml\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/sub/Signature.xml", "<Signature/>");

        runHandler();

        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "多级 BaseLoc 时应删除其顶层目录 Sign_0");
        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR)),
                "Signs 目录变空后应被删除");
    }

    @Test
    @DisplayName("BaseLoc 不含斜杠时把整个 BaseLoc 当作目录名处理")
    void handleUsesWholeBaseLocWhenNoSlash() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeSignatures("  <Signature ID=\"s001\" BaseLoc=\"Sign_0\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");

        runHandler();

        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "BaseLoc 即目录名时该目录应被删除");
        assertFalse(Files.exists(workDir.resolve("Doc_0/Signs/Signatures.xml")),
                "签名列表文件应被删除");
    }

    @Test
    @DisplayName("BaseLoc 以斜杠开头时不删除包内同名目录，但其它清理仍然完成")
    void handleWithAbsoluteBaseLocKeepsSignaturesDir() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeSignatures("  <Signature ID=\"s001\" BaseLoc=\"/Sign_0/Signature.xml\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");

        runHandler();

        assertTrue(Files.isDirectory(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "以斜杠开头的 BaseLoc 被解析为绝对路径，包内目录不应被删除");
        assertFalse(Files.exists(workDir.resolve("Doc_0/Signs/Signatures.xml")),
                "签名列表文件仍应被删除");
        assertFalse(readOfdXml().contains("<Signatures>"),
                "OFD.xml 中的 Signatures 引用仍应被移除");
    }

    @Test
    @DisplayName("某个签名目录不存在时不影响其它签名的清理")
    void handleIgnoresMissingSignatureDir() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeSignatures(
                "  <Signature ID=\"s001\" BaseLoc=\"Sign_missing/Signature.xml\"/>",
                "  <Signature ID=\"s002\" BaseLoc=\"Sign_0/Signature.xml\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");

        runHandler();

        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "存在的签名目录仍应被删除");
        assertFalse(Files.exists(workDir.resolve("Doc_0/Signs/Signatures.xml")),
                "签名列表文件应被删除");
    }

    @Test
    @DisplayName("Signature 缺少 Type 属性时按默认签章处理，不抛异常")
    void handleAcceptsSignatureWithoutType() throws IOException {
        writeOfdXml("<Signatures>" + SIG_LOC_ABS + "</Signatures>");
        writeDocumentXml();
        writeSignatures("  <Signature ID=\"s001\" BaseLoc=\"Sign_0/Signature.xml\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");

        runHandler();

        assertFalse(Files.exists(workDir.resolve(SIGNS_DIR + "/Sign_0")),
                "缺少 Type 属性的签名同样应被清理");
    }

    @Test
    @DisplayName("存在多个 DocBody 时，所有 DocBody 中的 Signatures 引用都被移除")
    void handleRemovesSignaturesFromAllDocBodies() throws IOException {
        String ofdXml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<OFD Version=\"1.2\" DocType=\"OFD\">"
                + "<DocBody><DocInfo><DocID>id-0</DocID></DocInfo>"
                + "<DocRoot>Doc_0/Document.xml</DocRoot>"
                + "<Signatures>" + SIG_LOC_ABS + "</Signatures></DocBody>"
                + "<DocBody><DocInfo><DocID>id-1</DocID></DocInfo>"
                + "<DocRoot>Doc_1/Document.xml</DocRoot>"
                + "<Signatures>/Doc_1/Signs/Signatures.xml</Signatures></DocBody>"
                + "</OFD>";
        writeFile("OFD.xml", ofdXml);
        writeDocumentXml();
        writeSignatures("  <Signature ID=\"s001\" BaseLoc=\"Sign_0/Signature.xml\"/>");
        writeFile(SIGNS_DIR + "/Sign_0/Signature.xml", "<Signature/>");

        runHandler();

        String updated = readOfdXml();
        assertFalse(updated.contains("Signatures"),
                "所有 DocBody 中的 Signatures 引用都应被移除，实际内容：" + updated);
        assertEquals(2, countOccurrences(updated, "<DocBody>"),
                "DocBody 节点本身不应被移除");
        assertTrue(updated.contains("Doc_0/Document.xml") && updated.contains("Doc_1/Document.xml"),
                "DocRoot 引用应保留");
        assertFalse(Files.exists(workDir.resolve("Doc_0/Signs/Sign_0")),
                "签名描述目录应被删除");
    }

    // ------------------------------------------------------------------
    // 辅助方法
    // ------------------------------------------------------------------

    private void runHandler() throws IOException {
        Path root = workDir.toAbsolutePath();
        try (OFDReader reader = new OFDReader(root.toString(), false)) {
            assertNotNull(reader.getWorkDir(), "工作目录不应为空");
            OFDDir ofdDir = reader.getOFDDir();
            new SignatureHandler().handle(reader, ofdDir);
        }
    }

    private void writeOfdXml(String signaturesElement) throws IOException {
        String xml = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<OFD Version=\"1.2\" DocType=\"OFD\">"
                + "<DocBody><DocInfo><DocID>id-0</DocID></DocInfo>"
                + "<DocRoot>Doc_0/Document.xml</DocRoot>"
                + signaturesElement
                + "</DocBody></OFD>";
        writeFile("OFD.xml", xml);
    }

