    /**
     * KEY: 字族名、字体名、PSName，如 SimSun、SitkaBanner-Bold
     * VALUE: 字体所在绝对路径
     */
    private final Map<String, String> fontNamePathMapping = new ConcurrentHashMap<>();
    /**
