        assertPageDimensions(nullIndexesOfd, new float[][]{{120, 220}, {180, 280}});

        Path emptyIndexesOfd = tempDir.resolve("empty-indexes.ofd");
        try (PDFConverter converter = new PDFConverter(emptyIndexesOfd)) {
            converter.convert(pdf, new int[0]);
        }
        assertPageDimensions(emptyIndexesOfd, new float[][]{{120, 220}, {180, 280}});
