/**
 * 字体
 *
 * @author 权观宇
 * @since 2020-02-03 02:04:29
 */
public class Font {
    /**
     * 字体名称
     */
    private String name;

    /**
     * 字体族名称
     */
    private String familyName;

    /**
     * 字体文件路径
     */
    private Path fontFile;

    /**
     * 可打印字符宽度映射
     */
    private double[] printableAsciiWidthMap = null;
    /**
     * 缓存的AWT字体
     */
    private java.awt.Font fontObj;

    /**
     * 是否可嵌入OFD文件包
     */
    private boolean embeddable = true;

    private Font() {
    }

    /**
     * @return 默认字体（Noto思源宋体）
     */
    public static Font getDefault() {
        return FontName.SimSun.font();
    }

    public Font(String name, String familyName, Path fontFile) {
        this.name = name;
        this.familyName = familyName;
        if (fontFile == null || Files.notExists(fontFile)) {
            throw new IllegalArgumentException("字体文件(fontFile)不存在");
        }
        this.setFontFile(fontFile);
    }

    public Font(String name, String familyName) {
        this.name = name;
        this.familyName = familyName;
    }

    public Font(String name, Path fontFile) {
        this.name = name;
        if (fontFile == null || Files.notExists(fontFile)) {
            throw new IllegalArgumentException("字体文件(fontFile)不存在");
        }
        this.setFontFile(fontFile);

    }

    /**
     * 创建字体并指定 可打印字符宽度缩放倍数
     *
     * @param name                   字形名
     * @param familyName             字族名
     * @param fontFile               字形文件路径
     * @param printableAsciiWidthMap 可打印字符映射表，用于处理字符的宽度
     */
    public Font(String name, String familyName, Path fontFile, double[] printableAsciiWidthMap) {
        this.name = name;
        this.familyName = familyName;
        this.fontFile = fontFile;
        this.printableAsciiWidthMap = printableAsciiWidthMap;
    }

    /**
     * 字体是否存在预设的字符宽度映射表
     *
     * @return true - 存在；false - 不存在
     */
    public boolean hasWidthMath() {
        return this.printableAsciiWidthMap != null && this.printableAsciiWidthMap.length > 0;
    }

    /**
     * 获取字符占比
     *
     * @param txt 字符
     * @return 0~1 占比
     */
    public double getCharWidthScale(char txt) {
        // 如果存在字符映射那么从字符映射中获取宽度占比
        if (printableAsciiWidthMap != null) {
            // 所有 ASCII码均采用半角
            if (txt >= 32 && txt <= 126) {
                // 根据可打印宽度比例映射表打印
                return printableAsciiWidthMap[txt - 32];
            } else {
                // 非英文字符
                return 1;
            }
        } else {
            // 不存在字符映射，那么认为是等宽度比例 ASCII 为 0.5 其他为 1
            return (txt >= 32 && txt <= 126) ? 0.5 : 1;
        }
    }

    /**
     * 设置可打印字符宽度映射表
     * <p>
     * 在使用操作系统字体时，默认采用ACSII 0.5 其余1的比例计算宽度，因此可能需要手动设置宽度比例才可以达到相应的效果
     *
     * @param map 映射比例表
     * @return this
     */
    public Font setPrintableAsciiWidthMap(double[] map) {
        this.printableAsciiWidthMap = map;
        return this;
    }

    /**
     * 获取字体全名
     *
     * @return 字体全名
     */
    public String getCompleteFontName() {
        if (familyName == null) {
            return name;
        } else {
            return name + "-" + familyName;
        }
    }

    public String getName() {
        return name;
    }

    public Font setName(String name) {
        this.name = name;
        return this;
    }

     * @return 字体宽度
     */
    public Integer getFontWeight() {
        return fontWeight;
    }

    /**
     * 获取字符方向
     *
     * @return 字符方向
     */
    public int getCharDirection() {
        return charDirection;
    }

    /**
     * 设置字符方向
     *
     * @param charDirection 字符方向(charDirection) 允许值：0、90、180、270
     * @return this
     */
    public FontSetting setCharDirection(int charDirection) {
        if (charDirection == 0 || charDirection == 90 || charDirection == 180 || charDirection == 270) {
            this.charDirection = charDirection;
        } else {
            throw new IllegalArgumentException("字符方向(charDirection) 允许值：0、90、180、270，错误值：" + charDirection);
        }
        return this;
    }

    /**
     * 获取阅读方向
     *
     * @return 阅读方向
     */
    public int getReadDirection() {
        return readDirection;
    }


    /**
     * 获取字间距
     *
     * @return 字间距，单位毫米mm，默认值0
     */
    @Override
    public Double getLetterSpacing() {
        return letterSpacing;
    }

    /**
     * 设置字间距
     * <p>
     * 如果字间距小于0，那么将会自动修正为0
     *
     * @param letterSpacing 字间距，单位毫米mm
     * @return this
     */
    public FontSetting setLetterSpacing(double letterSpacing) {
        if (letterSpacing < 0) {
            letterSpacing = 0;
        }
        this.letterSpacing = letterSpacing;
        return this;
    }

    /**
     * 设置阅读方向
     *
     * @param readDirection 设置阅读方向(charDirection) 允许值：0、90、180、270
     * @return this
     */
    public FontSetting setReadDirection(int readDirection) {
        if (readDirection == 0 || readDirection == 90 || readDirection == 180 || readDirection == 270) {
            this.readDirection = readDirection;
        } else {
            throw new IllegalArgumentException("阅读方向(readDirection) 允许值：0、90、180、270，错误值：" + readDirection);
        }
        return this;
    }

    /**
     * 设置字体宽度
     *
     * @param fontWeight 字体宽度，可选值：100、200、300、400、500、600、700、800、900
     * @return this
     */
    public FontSetting setFontWeight(Integer fontWeight) {
        switch (fontWeight) {
            case 100:
            case 200:
            case 300:
            case 400:
            case 500:
            case 600:
            case 700:
            case 800:
            case 900:
                this.fontWeight = fontWeight;
                break;
            default:
                throw new NumberFormatException("字体宽度(fontWeight)可选值： 100、200、300、400、500、600、700、800、900");
        }
        return this;
    }

    /**
     * 字符宽度
     *
     * @param c 字符
     * @return 宽度单位毫米
     */
    public Double charWidth(char c) {
        return box(c).getWidth();
    }

    /**
     * 返回文字所占空间
     *
     * @param c 文字
     * @return 文字所占空间
     */
    public Rectangle2D box(char c) {
        if (fontObj.hasWidthMath()) {
            // 如果存在预设的字符映射表那么查表计算
            return new Rectangle2D.Double(0, 0, fontObj.getCharWidthScale(c) * fontSize, fontSize);
        }
        // 如果字体缓存为空，则加载字体
        if (awtFont == null) {
            // 尝试从字体中获取AWT字体对象
            awtFont = fontObj.getFontObj();
            if (awtFont == null) {
                // 尝试从环境变量中加载字体
                awtFont = EnvFont.getFont(fontObj.getName(), fontObj.getFamilyName());
            }
            if (awtFont == null) {
                awtFont = EnvFont.getDefaultFont();
            }
            awtFont = awtFont.deriveFont((float) fontSize);
        }

        return awtFont.getStringBounds(String.valueOf(c), EnvFont.FRCtx());
    }


    @Override
    public FontSetting clone() {
        return new FontSetting()
                .setFont(this.fontObj)
                .setItalic(this.italic)
                .setFontSize(this.fontSize)
                .setFontWeight(this.fontWeight)
                .setCharDirection(this.charDirection)
                .setReadDirection(this.readDirection)
                .setTextAlign(this.textAlign);
    }
}

