     * 资源ID自增器
     */
    private int nextResId = 100;

    @BeforeEach
    void setUp() throws Exception {
        ofdDir = OFDDir.newOFD();
        docDir = ofdDir.obtainDocDefault();
        Document document = new Document();
        document.setCommonData(new CT_CommonData().setMaxUnitID(99));
        docDir.setDocument(document);
        manager = new ResManager(ofdDir, docDir, new AtomicInteger(99));
    }

    @AfterEach
    void tearDown() {
        if (ofdDir != null) {
            ofdDir.clean();
        }
    }

    /**
     * 构造一个字体描述对象
     *
     * @param fontName   字形名（null表示不设置）
     * @param familyName 字形族名（null表示不设置）
     * @param fontFile   内嵌字形文件路径（null表示不设置）
     * @return 字体描述对象
     */
    private CT_Font newFont(String fontName, String familyName, String fontFile) {
        CT_Font font = new CT_Font();
        if (fontName != null) {
            font.setFontName(fontName);
        }
        if (familyName != null) {
            font.setFamilyName(familyName);
        }
        if (fontFile != null) {
            font.setFontFile(fontFile);
        }
        font.setID(nextResId++);
        return font;
    }

    /**
     * 将一组字体加入到一个新的 Fonts 资源中，并挂载到资源清单上
     *
     * @param res    资源清单
     * @param fonts  字体列表
     */
    private void addFontsResource(Res res, CT_Font... fonts) {
        Fonts container = new Fonts();
        for (CT_Font font : fonts) {
            container.addFont(font);
        }
        res.addResource(container);
    }

    @Test
    @DisplayName("字体名称为null时直接返回null，且不创建任何资源清单")
    void nullNameReturnsNull() throws Exception {
        assertNull(manager.getFont(null));

        // 提前返回，不应产生任何资源清单副作用
        assertFalse(docDir.exist(DocDir.PublicResFileName));
        assertFalse(docDir.exist(DocDir.DocumentResFileName));
        CT_CommonData commonData = manager.getDocDir().getDocument().getCommonData();
        assertTrue(commonData.getPublicResList().isEmpty());
        assertTrue(commonData.getDocumentResList().isEmpty());
    }

    @Test
    @DisplayName("字体名称为空字符串时直接返回null，且不创建任何资源清单")
    void emptyNameReturnsNull() throws Exception {
        assertNull(manager.getFont(""));

        assertFalse(docDir.exist(DocDir.PublicResFileName));
        assertFalse(docDir.exist(DocDir.DocumentResFileName));
        CT_CommonData commonData = manager.getDocDir().getDocument().getCommonData();
        assertTrue(commonData.getPublicResList().isEmpty());
        assertTrue(commonData.getDocumentResList().isEmpty());
    }

    @Test
    @DisplayName("空资源清单中查找不存在的字体返回null，同时创建公共与文档资源清单")
    void unknownNameReturnsNullAndCreatesResources() throws Exception {
        assertNull(manager.getFont("NotExistFont"));

        // 查找过程会创建并登记公共资源与文档资源清单
        assertTrue(docDir.exist(DocDir.PublicResFileName));
        assertTrue(docDir.exist(DocDir.DocumentResFileName));
        CT_CommonData commonData = manager.getDocDir().getDocument().getCommonData();
        assertEquals(1, commonData.getPublicResList().size());
        assertEquals("PublicRes.xml", commonData.getPublicResList().get(0).toString());
        assertEquals(1, commonData.getDocumentResList().size());
        assertEquals("DocumentRes.xml", commonData.getDocumentResList().get(0).toString());
    }

    @Test
    @DisplayName("按字形名精确匹配公共资源中的字体，且无字体文件时路径为null")
    void findsByFontNameInPublicRes() {
        CT_Font font = newFont("Arial", null, null);
        addFontsResource(manager.pubRes(), font);

        ExistCTFont result = manager.getFont("Arial");

        assertNotNull(result);
        assertSame(font, result.font);
        assertEquals("Arial", result.font.getFontName());
        // 字体没有内嵌文件，绝对路径为null
        assertNull(result.absPath);
        // 只命中公共资源，文档资源清单不应被创建
        assertFalse(docDir.exist(DocDir.DocumentResFileName));
    }

    @Test
    @DisplayName("查找时忽略大小写（字形名）")
    void fontNameMatchIsCaseInsensitive() {
        CT_Font font = newFont("Arial", null, null);
        addFontsResource(manager.pubRes(), font);

        assertSame(font, manager.getFont("ARIAL").font);
        assertSame(font, manager.getFont("aRiaL").font);
        assertSame(font, manager.getFont("arial").font);
    }

    @Test
    @DisplayName("可以通过字形族名匹配字体，且忽略大小写")
    void findsByFamilyName() {
        CT_Font font = newFont("SimHei-Bold", "SimHei", null);
        addFontsResource(manager.pubRes(), font);

        ExistCTFont byFamily = manager.getFont("simhei");
        assertNotNull(byFamily);
        assertSame(font, byFamily.font);

        // 字形名依然可以命中
        assertSame(font, manager.getFont("SIMHEI-BOLD").font);
    }

    @Test
    @DisplayName("字体缺少族名时不会抛出空指针异常")
    void fontWithoutFamilyNameDoesNotFail() {
        CT_Font font = newFont("OnlyFontName", null, null);
        addFontsResource(manager.pubRes(), font);

        ExistCTFont result = manager.getFont("onlyfontname");

        assertNotNull(result);
        assertSame(font, result.font);
        assertNull(result.font.getFamilyName());
    }

    @Test
    @DisplayName("支持中文族名与英文字形名的混合匹配")
    void supportsNonAsciiNames() {
        CT_Font font = newFont("SimSun", "宋体", null);
        addFontsResource(manager.pubRes(), font);

        assertSame(font, manager.getFont("宋体").font);
        assertSame(font, manager.getFont("simsun").font);
    }

    @Test
    @DisplayName("名称首尾空格不会被裁剪，因此匹配失败")
    void nameIsNotTrimmed() {
        CT_Font font = newFont("Arial", null, null);
        addFontsResource(manager.pubRes(), font);

        assertNull(manager.getFont(" Arial "));
        assertNotNull(manager.getFont("Arial"));
