     */
    private static void assertSameFont(CT_Font expected, CT_Font actual) {
        assertNotNull(actual, "未能查找到字体");
        assertSame(unwrapProxy(expected), unwrapProxy(actual), "返回的字体不是期望的字体");
        assertEquals(expected.getID().getId(), actual.getID().getId(), "返回字体的ID不符");
        assertEquals(expected.getFontName(), actual.getFontName(), "返回字体的字形名不符");
