    }

    /**
     * 递归取出最内层的XML元素对象
     *
     * @param element XML元素（可能是代理对象）
     * @return 最内层的XML元素对象
     */
    private static Element unwrapProxy(Element element) {
        Element res = element;
        while (res instanceof DefaultElementProxy) {
            res = ((DefaultElementProxy) res).getProxy();
        }
        return res;
    }

