import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 测试 {@link ResManager#getFont(String)} 的字体检索行为。
 */
@DisplayName("ResManager.getFont 字体查找测试")
public class ResManagerGetFontTests {

    /**
     * 新建的OFD虚拟容器
     */
    private OFDDir ofdDir;

    /**
     * 文档容器（Doc_0）
     */
    private DocDir docDir;

    /**
     * 被测试的资源管理器
     */
    private ResManager manager;

    /**
     * 断言查找结果对应的正是期望的字体
     * <p>
     * {@code Res#getFonts()} 每次都会重新包装XML元素，因此不能直接比较对象引用，
     * 这里通过比较被代理的XML元素对象以及字体属性来确定返回的字体。
     *
     * @param expected 期望的字体
     * @param actual   实际查找到的字体
     */
    private static void assertSameFont(CT_Font expected, CT_Font actual) {
        assertNotNull(actual, "未能查找到字体");
        assertSame(unwrapProxy(expected), unwrapProxy(actual), "返回的字体不是期望的字体");
        assertEquals(expected.getID().getId(), actual.getID().getId(), "返回字体的ID不符");
        assertEquals(expected.getFontName(), actual.getFontName(), "返回字体的字形名不符");
        assertEquals(expected.getFamilyName(), actual.getFamilyName(), "返回字体的族名不符");
        assertEquals(expected.getFontFile(), actual.getFontFile(), "返回字体的字体文件不符");
    }

    /**
     * 递归取出最内层的XML元素对象
     *
     * @param element XML元素（可能是代理对象）
     * @return 最内层的XML元素对象
     */
    private static Element unwrapProxy(Element element) {
        Element res = element;
        while (res instanceof DefaultElementProxy) {
            res = ((DefaultElementProxy) res).getProxy();
        }
        return res;
    }

    @Test
    @DisplayName("字体名称为null时直接返回null，且不创建任何资源清单")
    void nullNameReturnsNull() throws Exception {
        assertNull(manager.getFont(null));

        // 提前返回，不应产生任何资源清单副作用
        assertFalse(docDir.exist(DocDir.PublicResFileName));
        assertFalse(docDir.exist(DocDir.DocumentResFileName));
        CT_CommonData commonData = manager.getDocDir().getDocument().getCommonData();
        assertTrue(commonData.getPublicResList().isEmpty());
        assertTrue(commonData.getDocumentResList().isEmpty());
    }

    @Test
    @DisplayName("字体名称为空字符串时直接返回null，且不创建任何资源清单")
    void emptyNameReturnsNull() throws Exception {
        assertNull(manager.getFont(""));

        assertFalse(docDir.exist(DocDir.PublicResFileName));
        assertFalse(docDir.exist(DocDir.DocumentResFileName));
        CT_CommonData commonData = manager.getDocDir().getDocument().getCommonData();
        assertTrue(commonData.getPublicResList().isEmpty());
        assertTrue(commonData.getDocumentResList().isEmpty());
    }

    @Test
    @DisplayName("空资源清单中查找不存在的字体返回null，同时创建公共与文档资源清单")
    void unknownNameReturnsNullAndCreatesResources() throws Exception {
        assertNull(manager.getFont("NotExistFont"));

        // 查找过程会创建并登记公共资源与文档资源清单
        assertTrue(docDir.exist(DocDir.PublicResFileName));
        assertTrue(docDir.exist(DocDir.DocumentResFileName));
        CT_CommonData commonData = manager.getDocDir().getDocument().getCommonData();
        assertEquals(1, commonData.getPublicResList().size());
        assertEquals("PublicRes.xml", commonData.getPublicResList().get(0).toString());
        assertEquals(1, commonData.getDocumentResList().size());
        assertEquals("DocumentRes.xml", commonData.getDocumentResList().get(0).toString());
    }

    @Test
    @DisplayName("按字形名精确匹配公共资源中的字体，且无字体文件时路径为null")
    void findsByFontNameInPublicRes() {
        CT_Font font = newFont("Arial", null, null);
        addFontsResource(manager.pubRes(), font);

        ExistCTFont result = manager.getFont("Arial");

        assertNotNull(result);
        assertSameFont(font, result.font);
        assertEquals("Arial", result.font.getFontName());
        // 字体没有内嵌文件，绝对路径为null
        assertNull(result.absPath);
        // 只命中公共资源，文档资源清单不应被创建
        assertFalse(docDir.exist(DocDir.DocumentResFileName));
    }

    @Test
    @DisplayName("查找时忽略大小写（字形名）")
    void fontNameMatchIsCaseInsensitive() {
        CT_Font font = newFont("Arial", null, null);
        addFontsResource(manager.pubRes(), font);

        assertSameFont(font, manager.getFont("ARIAL").font);
        assertSameFont(font, manager.getFont("aRiaL").font);
        assertSameFont(font, manager.getFont("arial").font);
    }

    @Test
    @DisplayName("可以通过字形族名匹配字体，且忽略大小写")
    void findsByFamilyName() {
        CT_Font font = newFont("SimHei-Bold", "SimHei", null);
        addFontsResource(manager.pubRes(), font);

        ExistCTFont byFamily = manager.getFont("simhei");
        assertNotNull(byFamily);
        assertSameFont(font, byFamily.font);

        // 字形名依然可以命中
        assertSameFont(font, manager.getFont("SIMHEI-BOLD").font);
    }

    @Test
    @DisplayName("字体缺少族名时不会抛出空指针异常")
    void fontWithoutFamilyNameDoesNotFail() {
        CT_Font font = newFont("OnlyFontName", null, null);
        addFontsResource(manager.pubRes(), font);

        ExistCTFont result = manager.getFont("onlyfontname");

        assertNotNull(result);
        assertSameFont(font, result.font);
        assertNull(result.font.getFamilyName());
    }

    @Test
    @DisplayName("支持中文族名与英文字形名的混合匹配")
    void supportsNonAsciiNames() {
        CT_Font font = newFont("SimSun", "宋体", null);
        addFontsResource(manager.pubRes(), font);

        assertSameFont(font, manager.getFont("宋体").font);
        assertSameFont(font, manager.getFont("simsun").font);
    }

    @Test
    @DisplayName("名称首尾空格不会被裁剪，因此匹配失败")
    void nameIsNotTrimmed() {
        CT_Font font = newFont("Arial", null, null);
        addFontsResource(manager.pubRes(), font);

        assertNull(manager.getFont(" Arial "));
        assertNotNull(manager.getFont("Arial"));
    }

    @Test
    @DisplayName("同一Fonts资源中多个字体匹配时返回最后一个")
    void lastMatchInSameFontsResourceWins() {
        CT_Font first = newFont("DupFont", null, null);
        CT_Font second = newFont("DupFont", null, null);
        CT_Font third = newFont("DupFont", null, null);
        CT_Font other = newFont("OtherFont", null, null);
        addFontsResource(manager.pubRes(), first, second, third, other);

        ExistCTFont result = manager.getFont("dupfont");

        assertNotNull(result);
        assertSameFont(third, result.font);
    }

    @Test
    @DisplayName("多个Fonts资源中匹配时返回最后一个匹配的字体")
    void lastMatchAcrossFontsResourcesWins() {
        CT_Font first = newFont("Same", null, null);
        CT_Font second = newFont("Same", null, null);
        Res pubRes = manager.pubRes();
        addFontsResource(pubRes, first);
        addFontsResource(pubRes, newFont("Middle", null, null), second);
        // 末尾追加一个不匹配的资源，不应影响结果
        addFontsResource(pubRes, newFont("Tail", null, null));

        ExistCTFont result = manager.getFont("same");

        assertNotNull(result);
        assertSameFont(second, result.font);
    }

    @Test
    @DisplayName("字形名与族名交替命中时，仍以最后遍历到的字体为准")
    void lastMatchedFontWinsRegardlessOfMatchedAttribute() {
        CT_Font byFontName = newFont("Target", null, null);
        CT_Font byFamilyName = newFont("Another", "Target", null);
        addFontsResource(manager.pubRes(), byFontName, byFamilyName);

        ExistCTFont result = manager.getFont("target");

        assertNotNull(result);
        assertSameFont(byFamilyName, result.font);
        assertEquals("Another", result.font.getFontName());
    }

    @Test
    @DisplayName("公共资源无法命中时，回退到文档资源中查找")
    void fallsBackToDocumentRes() {
        addFontsResource(manager.pubRes(), newFont("Arial", null, null));
        CT_Font docFont = newFont("TimesNewRoman", "Times New Roman", null);
        addFontsResource(manager.docRes(), docFont);

        ExistCTFont result = manager.getFont("times new roman");

        assertNotNull(result);
        assertSameFont(docFont, result.font);
    }

    @Test
    @DisplayName("公共资源优先于文档资源：同名字体返回公共资源中的对象")
    void publicResTakesPrecedenceOverDocumentRes() {
        CT_Font publicFont = newFont("Shared", null, null);
        CT_Font documentFont = newFont("Shared", null, null);
        addFontsResource(manager.pubRes(), publicFont);
        addFontsResource(manager.docRes(), documentFont);

        ExistCTFont result = manager.getFont("shared");

        assertNotNull(result);
        assertSameFont(publicFont, result.font);
    }

    @Test
    @DisplayName("公共资源与文档资源均无匹配字体时返回null")
    void returnsNullWhenNoFontMatchesAnywhere() {
        addFontsResource(manager.pubRes(), newFont("Arial", "ArialFamily", null));
        addFontsResource(manager.docRes(), newFont("Courier", "CourierFamily", null));

        assertNull(manager.getFont("SimSun"));
    }

    @Test
    @DisplayName("字体文件存在于文档根目录时，返回对应的绝对路径")
    void resolvesFontFileAbsolutePath() throws IOException {
        Path fontFile = ofdDir.getContainerPath().resolve("embedded.ttf");
        Files.write(fontFile, "fake-font".getBytes(StandardCharsets.UTF_8));

        CT_Font font = newFont("Arial", null, "embedded.ttf");
        addFontsResource(manager.pubRes(), font);

        ExistCTFont result = manager.getFont("Arial");

        assertNotNull(result);
        assertSameFont(font, result.font);
        assertNotNull(result.absPath);
        assertEquals(fontFile, result.absPath);
        assertTrue(Files.exists(result.absPath));
    }

    @Test
    @DisplayName("字体文件在容器中不存在时，返回的绝对路径为null但字体对象仍然返回")
    void missingFontFileYieldsNullPath() {
        CT_Font font = newFont("Arial", null, "not-exist.ttf");
        addFontsResource(manager.pubRes(), font);

        ExistCTFont result = manager.getFont("Arial");

        assertNotNull(result);
        assertSameFont(font, result.font);
        assertNull(result.absPath);
    }

    @Test
    @DisplayName("根容器为null时不解析字体文件路径，但字体对象仍然返回")
    void nullRootYieldsNullPath() throws IOException {
        Path fontFile = ofdDir.getContainerPath().resolve("embedded.ttf");
        Files.write(fontFile, "fake-font".getBytes(StandardCharsets.UTF_8));

        // 使用缺少根容器的构造器（root为null）
        ResManager noRootManager = new ResManager(docDir, new AtomicInteger(99));
        CT_Font font = newFont("Arial", null, "embedded.ttf");
        addFontsResource(noRootManager.pubRes(), font);

        ExistCTFont result = noRootManager.getFont("Arial");

        assertNotNull(result);
        assertSameFont(font, result.font);
        assertNull(result.absPath);
    }

    @Test
    @DisplayName("资源清单中存在缺少字形名的字体时抛出IllegalArgumentException")
    void fontWithoutFontNameAttributeThrows() {
        CT_Font brokenFont = newFont(null, null, null);
        addFontsResource(manager.pubRes(), brokenFont);

        IllegalArgumentException ex = assertThrows(IllegalArgumentException.class,
                () -> manager.getFont("Arial"));
        assertEquals("字形名（fontName）不能为空", ex.getMessage());
    }
}

