     * @param ctm ctm对象
     * @return 矩阵对象
     */
    private static double[] getMatrix(ST_Array ctm) {
        List<String> ctmArray = ctm.getArray();
        double[] matrix = new double[ctmArray.size()];
        for (int i = 0; i < ctmArray.size(); i++) {
            matrix[i] = Double.parseDouble(ctmArray.get(i));
        }
        return matrix;
    }

    /**
     * 合并关键字位置对象
