 * @param deltaX        X偏移量
 * @param fontSize      文字字号
 * @return 文本宽度
 */
private static double getStringWidth(int textIndex, int keywordLength, List<Float> deltaX, Double fontSize) {
    double width = fontSize;
    for (int i = textIndex; i < textIndex + keywordLength - 1 && i < deltaX.size(); i++) {
        width += deltaX.get(i);
    }
    return width;
}

