package org.ofdrw.reader.keyword;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.ofdrw.core.basicType.ST_Box;
import org.ofdrw.reader.OFDReader;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.zip.ZipEntry;
import java.util.zip.ZipOutputStream;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 针对 {@link KeywordExtractor#getKeyWordPositionList(OFDReader, String[], int[])} 的单元测试。
 *
 * <p>测试使用运行期构造的最小 OFD 包（OFD.xml / Document.xml / PublicRes.xml / 各页 Content.xml），
 * 因此文档内容、页数、文本定位坐标完全可控且与本地资源文件无关。</p>
 */
public class KeywordExtractorGetKeyWordPositionListTests {

    @TempDir
    Path tempDir;

    private static final String OFD_XML = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
            + "<ofd:OFD xmlns:ofd=\"http://www.ofdspec.org/2016\" Version=\"1.0\" DocType=\"OFD\"><ofd:DocBody>"
            + "<ofd:DocInfo><ofd:DocID>unit-test-doc</ofd:DocID><ofd:Creator>unit-test</ofd:Creator></ofd:DocInfo>"
            + "<ofd:DocRoot>Doc_0/Document.xml</ofd:DocRoot></ofd:DocBody></ofd:OFD>";

    private static final String PUBLIC_RES = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
            + "<ofd:Res xmlns:ofd=\"http://www.ofdspec.org/2016\" BaseLoc=\"Res\"><ofd:Fonts>"
            + "<ofd:Font FontName=\"宋体\" FamilyName=\"宋体\" ID=\"3\"/></ofd:Fonts></ofd:Res>";

    private static final double EPS = 1e-6;

    // ------------------------------------------------------------------
    // OFD 包构造工具
    // ------------------------------------------------------------------

    private static void putEntry(ZipOutputStream zos, String name, String content) throws IOException {
        zos.putNextEntry(new ZipEntry(name));
        zos.write(content.getBytes(StandardCharsets.UTF_8));
        zos.closeEntry();
    }

    private static String documentXml(int pageCount) {
        StringBuilder sb = new StringBuilder();
        sb.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n");
        sb.append("<ofd:Document xmlns:ofd=\"http://www.ofdspec.org/2016\"><ofd:CommonData>");
        sb.append("<ofd:PageArea><ofd:PhysicalBox>0 0 210 297</ofd:PhysicalBox></ofd:PageArea>");
        sb.append("<ofd:PublicRes>PublicRes.xml</ofd:PublicRes><ofd:MaxUnitID>1000</ofd:MaxUnitID>");
        sb.append("</ofd:CommonData><ofd:Pages>");
        for (int i = 0; i < pageCount; i++) {
            sb.append("<ofd:Page ID=\"").append(i + 10).append("\" BaseLoc=\"Pages/Page_")
                    .append(i).append("/Content.xml\"/>");
        }
        sb.append("</ofd:Pages></ofd:Document>");
        return sb.toString();
    }

    private static String pageXml(String layerContent) {
        return "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n"
                + "<ofd:Page xmlns:ofd=\"http://www.ofdspec.org/2016\"><ofd:Content><ofd:Layer ID=\"2\">"
                + layerContent
                + "</ofd:Layer></ofd:Content></ofd:Page>";
    }

    /**
     * 构造一个文字对象，文字定位起始点固定为 X=0、Y=3。
     */
    private static String textObject(int id, String boundary, String size, String deltaX, String content) {
        return "<ofd:TextObject ID=\"" + id + "\" Boundary=\"" + boundary + "\" Font=\"3\" Size=\"" + size + "\">"
                + "<ofd:TextCode X=\"0\" Y=\"3\" DeltaX=\"" + deltaX + "\">" + content + "</ofd:TextCode>"
                + "</ofd:TextObject>";
    }

    /**
     * 生成 OFD 文件，每个参数代表一页的层内容。
     */
    private Path writeOfd(String fileName, String... pageLayerContents) throws IOException {
        Path ofd = tempDir.resolve(fileName);
        try (ZipOutputStream zos = new ZipOutputStream(Files.newOutputStream(ofd))) {
            putEntry(zos, "OFD.xml", OFD_XML);
            putEntry(zos, "Doc_0/Document.xml", documentXml(pageLayerContents.length));
            putEntry(zos, "Doc_0/PublicRes.xml", PUBLIC_RES);
            for (int i = 0; i < pageLayerContents.length; i++) {
                putEntry(zos, "Doc_0/Pages/Page_" + i + "/Content.xml", pageXml(pageLayerContents[i]));
            }
        }
        return ofd;
    }

    // ------------------------------------------------------------------
    // 断言工具
    // ------------------------------------------------------------------

    private static void assertValidPosition(KeywordPosition position, int expectedPage, String expectedKeyword) {
        assertNotNull(position, "返回的关键字位置对象不应为 null");
        assertEquals(expectedPage, position.getPage(), "关键字所在页码不正确");
        assertEquals(expectedKeyword, position.getKeyword(), "关键字文本回填不正确");
        ST_Box box = position.getBox();
        assertNotNull(box, "关键字外接矩形不应为 null");
        assertNotNull(box.getTopLeftX(), "矩形左上角X不应为 null");
        assertNotNull(box.getTopLeftY(), "矩形左上角Y不应为 null");
        assertTrue(box.getWidth() > 0, "矩形宽度应大于0，实际为：" + box.getWidth());
        assertTrue(box.getHeight() > 0, "矩形高度应大于0，实际为：" + box.getHeight());
        assertTrue(Double.isFinite(box.getTopLeftX()) && Double.isFinite(box.getTopLeftY()),
                "矩形坐标应为有限值");
    }

    private static List<String> keywordsOf(List<KeywordPosition> positions) {
        List<String> keywords = new ArrayList<>();
        for (KeywordPosition position : positions) {
            keywords.add(position.getKeyword());
        }
        return keywords;
    }

    private static List<Integer> pagesOf(List<KeywordPosition> positions) {
        List<Integer> pages = new ArrayList<>();
        for (KeywordPosition position : positions) {
            pages.add(position.getPage());
        }
        return pages;
    }

    // ------------------------------------------------------------------
    // 单页正常匹配
    // ------------------------------------------------------------------

    @Test
    void keywordContainedInSingleTextCode_returnsExactBox() throws Exception {
        // Boundary 起点 (10,20)，TextCode 起点 (0,3)，每个字符水平前进 3mm，字号 3.0
        Path ofd = writeOfd("single.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "合同编号ABC"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"ABC"}, null);

            assertEquals(1, positions.size(), "关键字 ABC 在文档中出现一次");
            KeywordPosition position = positions.get(0);
            assertValidPosition(position, 1, "ABC");

            ST_Box box = position.getBox();
            // 起始字符索引为 4 => 起点 X = Boundary.X + 4 * DeltaX = 10 + 12
            assertEquals(22d, box.getTopLeftX(), EPS, "关键字起始X坐标应等于Boundary偏移与字符偏移之和");
            // 宽度 = 字号 + (关键字长度-1) * DeltaX = 3 + 2 * 3
            assertEquals(9d, box.getWidth(), EPS, "关键字宽度应为字号与字符间距的累加");
            // Y 方向：文字基线 Y = 20 + 3 = 23，矩形顶部 = 基线 - 字体高度
            assertEquals(23d, box.getTopLeftY() + box.getHeight(), EPS, "矩形底边应位于文字基线位置");
        }
    }

    @Test
    void keywordAppearsTwiceInOneTextCode_returnsOnePositionPerOccurrence() throws Exception {
        Path ofd = writeOfd("twice.ofd",
                textObject(4, "10 40 50 10", "3.0", "3", "关键字关键字"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"关键字"}, null);

            assertEquals(2, positions.size(), "同一文字定位中出现两次关键字应返回两个位置");
            assertValidPosition(positions.get(0), 1, "关键字");
            assertValidPosition(positions.get(1), 1, "关键字");
            assertEquals(10d, positions.get(0).getBox().getTopLeftX(), EPS, "第一次出现应位于文本起点");
            assertEquals(19d, positions.get(1).getBox().getTopLeftX(), EPS, "第二次出现应位于三个字符之后");
            assertTrue(positions.get(1).getBox().getTopLeftX() > positions.get(0).getBox().getTopLeftX(),
                    "后一次出现应位于前一次出现的右侧");
        }
    }

    @Test
    void multipleKeywords_returnPositionsInDocumentOrder() throws Exception {
        Path ofd = writeOfd("multiKeyword.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "合同编号ABC"),
                textObject(5, "10 40 50 10", "3.0", "3", "合同金额100元"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"合同", "ABC"}, null);

            assertEquals(2, positions.size(), "两个关键字各命中一次");
            assertEquals(Arrays.asList("合同", "ABC"), keywordsOf(positions), "结果应按文本定位顺序返回");
            assertEquals(Arrays.asList(1, 1), pagesOf(positions));
            assertValidPosition(positions.get(0), 1, "合同");
            assertValidPosition(positions.get(1), 1, "ABC");
        }
    }

    @Test
    void keywordNotPresent_returnsEmptyList() throws Exception {
        Path ofd = writeOfd("absent.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "合同编号ABC"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"不存在的关键字"}, null);
            assertTrue(positions.isEmpty(), "未命中的关键字应返回空列表");
        }
    }

    @Test
    void keywordMatchingIsCaseSensitive() throws Exception {
        Path ofd = writeOfd("case.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "OFD Reader"));

        try (OFDReader reader = new OFDReader(ofd)) {
            assertTrue(KeywordExtractor.getKeyWordPositionList(reader, new String[]{"ofd"}, null).isEmpty(),
                    "小写关键字不应匹配大写文本");
            List<KeywordPosition> upper = KeywordExtractor.getKeyWordPositionList(reader, new String[]{"OFD"}, null);
            assertEquals(1, upper.size(), "大小写完全一致时应命中");
            assertValidPosition(upper.get(0), 1, "OFD");
        }
    }

    @Test
    void emptyKeywordArray_returnsEmptyList() throws Exception {
        Path ofd = writeOfd("emptyKeywords.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "合同编号ABC"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{}, null);
            assertNotNull(positions, "空关键字数组应返回空列表而非 null");
            assertTrue(positions.isEmpty(), "空关键字数组应返回空列表");
        }
    }

    @Test
    void blankTextCodes_areIgnoredDuringSearch() throws Exception {
        Path ofd = writeOfd("blank.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "   ")
                        + textObject(5, "10 40 50 10", "3.0", "3", "目标文本")
                        + "<ofd:TextObject ID=\"6\" Boundary=\"10 60 50 10\" Font=\"3\" Size=\"3.0\"/>");

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"目标"}, null);
            assertEquals(1, positions.size(), "空白文字定位不应参与匹配");
            assertValidPosition(positions.get(0), 1, "目标");
        }
    }

    // ------------------------------------------------------------------
    // 跨文字定位（断字断行）匹配
    // ------------------------------------------------------------------

    @Test
    void keywordSplitAcrossTextCodes_isMergedIntoOnePosition() throws Exception {
        Path ofd = writeOfd("splitPrefix.ofd",
                textObject(6, "57.16 170.84 21.17 7.81", "4.0", "4 4 4 4", "重庆市马")
                        + textObject(7, "78.33 170.84 12.70 7.81", "4.0", "4 4", "上融资"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"重庆市马上融资"}, null);

            assertEquals(1, positions.size(), "跨文字定位的关键字应合并为一个位置");
            assertValidPosition(positions.get(0), 1, "重庆市马上融资");
            ST_Box box = positions.get(0).getBox();
            // 合并后的矩形应跨越两个文字对象（总宽度明显大于单个文字对象宽度）
            assertTrue(box.getWidth() > 21.17, "合并矩形宽度应大于第一个文字对象宽度，实际：" + box.getWidth());
            assertEquals(57.16d, box.getTopLeftX(), EPS, "合并矩形左边界应为第一个文字对象的左边界");
        }
    }

    @Test
    void keywordSuffixSplitAcrossTextCodes_isMergedIntoOnePosition() throws Exception {
        // 第一个文字对象只包含关键字的前缀（"合同号A" 中的 "A"），后续文字对象补全 "001"
        Path ofd = writeOfd("splitSuffix.ofd",
                textObject(8, "10 60 50 10", "3.0", "3 3 3 3", "合同号A")
                        + textObject(9, "30 60 50 10", "3.0", "3 3 3", "001"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"A001"}, null);

            assertEquals(1, positions.size(), "后缀跨文字定位的关键字应合并为一个位置");
            assertValidPosition(positions.get(0), 1, "A001");
            ST_Box box = positions.get(0).getBox();
            // 起点越过 "合同号" 三个字符 => 10 + 3*3
            assertEquals(19d, box.getTopLeftX(), EPS, "合并矩形左边界应从关键字首字符开始");
            assertTrue(box.getWidth() > 9d, "合并矩形应覆盖第二个文字对象中的字符");
        }
    }

    @Test
    void keywordSpanningTwoPages_isNotReported() throws Exception {
        // 第一页只包含关键字前缀，第二页包含剩余字符，关键字不应跨页合并
        Path ofd = writeOfd("crossPage.ofd",
                textObject(8, "10 60 50 10", "3.0", "3 3 3 3", "合同号A"),
                textObject(9, "10 20 50 10", "3.0", "3 3 3", "001"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"A001"}, null);
            assertTrue(positions.isEmpty(), "跨页的文字定位不应合并为关键字位置");
        }
    }

    // ------------------------------------------------------------------
    // 页码过滤
    // ------------------------------------------------------------------

    private Path twoPageDocument() throws IOException {
        return writeOfd("twoPages.ofd",
                textObject(4, "10 20 50 10", "3.0", "3", "报告编号R1"),
                textObject(4, "10 20 50 10", "3.0", "3", "报告编号R2"));
    }

    @Test
    void nullPages_searchesAllPages() throws Exception {
        Path ofd = twoPageDocument();
        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"报告"}, null);

            assertEquals(2, positions.size(), "未限定页码时应检索全部页面");
            assertEquals(Arrays.asList(1, 2), pagesOf(positions), "应分别在两页中命中");
            assertValidPosition(positions.get(0), 1, "报告");
            assertValidPosition(positions.get(1), 2, "报告");
        }
    }

    @Test
    void singlePageLimit_onlySearchesRequestedPage() throws Exception {
        Path ofd = twoPageDocument();
        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> secondPage = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"报告"}, new int[]{2});
            assertEquals(1, secondPage.size(), "只检索第2页应命中一次");
            assertEquals(2, secondPage.get(0).getPage());
            assertValidPosition(secondPage.get(0), 2, "报告");

            List<KeywordPosition> firstPage = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"报告"}, new int[]{1});
