            assertEquals(2, positions.size(), "第2页未包含关键字，不应返回位置");
            assertEquals(Arrays.asList(1, 3), pagesOf(positions), "结果应按页码升序返回");
        }
    }

    @Test
    void emptyPagesArray_behavesLikeNoPageLimit() throws Exception {
        Path ofd = twoPageDocument();
        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"报告"}, new int[]{});

            assertEquals(2, positions.size(), "空页码数组等价于不限定页码");
            assertEquals(Arrays.asList(1, 2), pagesOf(positions));
        }
    }

    @Test
    void duplicatedPageNumbers_doNotDuplicateResults() throws Exception {
        Path ofd = twoPageDocument();
        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
                    reader, new String[]{"报告"}, new int[]{2, 2});

