    @Test
    void keywordOnlyInTemplatePage_isFound() throws Exception {
        // 关键字只存在于模板页背景层，正文层不含关键字
        Path ofd = writeOfdWithTemplate("template.ofd",
                textObject(20, "20 30 60 10", "3.0", "3", "模板页背景水印"),
                textObject(21, "20 60 60 10", "3.0", "3", "正文内容"));

        try (OFDReader reader = new OFDReader(ofd)) {
            List<KeywordPosition> positions = KeywordExtractor.getKeyWordPositionList(
